# Now, we need to find all pairs of users who have questions with the same answer category
# The task says: "In your answer, list all pairs in the format (user_id_1, user_id_2), separated by newlines."

# Group users by category
from collections import defaultdict

users_by_category = defaultdict(list)
for user_id, question, category in classified:
    users_by_category[category].append(user_id)

# Generate all pairs within each category
pairs = []
for category, user_ids in users_by_category.items():
    if len(user_ids) < 2:
        continue
    # Generate all unordered pairs (i, j) where i < j
    for i in range(len(user_ids)):
        for j in range(i + 1, len(user_ids)):
            pairs.append(f"({user_ids[i]}, {user_ids[j]})")

print(f"Found {len(pairs)} user pairs with the same answer category.")
print("Sample pairs:")
for i in range(min(5, len(pairs))):
    print(pairs[i])

